/* hello_arc1 — vertical-slice demo for the ARC-1 host SDK.
 *
 * A ship drifts across a striped sky, bouncing at the screen edges.
 * UP/DOWN steer it vertically, A toggles the sky palette. Everything is
 * integer math driven only by arc1_input_*, so a replay always produces the
 * same frames. */
#include <arc1/game.h>

#include "arc1_assets.h" /* generated by `arc1 build` from assets/ */

#define STRIPE_H 12

static void draw_sky(int night, uint32_t frame) {
    static const arc1_color day[2] = {12, 1};
    static const arc1_color dusk[2] = {2, 1};
    const arc1_color *pal = night ? dusk : day;
    int scroll = (int)(frame % (2 * STRIPE_H));
    for (int y = -2 * STRIPE_H; y < ARC1_SCREEN_H; y += STRIPE_H)
        arc1_rect_fill(0, y + scroll, ARC1_SCREEN_W, STRIPE_H,
                       pal[((y + 2 * STRIPE_H) / STRIPE_H) & 1]);
    arc1_rect_fill(0, ARC1_SCREEN_H - 16, ARC1_SCREEN_W, 16, 3); /* ground */
}

int arc1_main(void) {
    if (arc1_init() != ARC1_OK) return 1;

    arc1_sprite ship;
    if (arc1_sprite_create(ARC1_ASSET_SHIP, ARC1_ASSET_SHIP_W,
                           ARC1_ASSET_SHIP_H, &ship) != ARC1_OK)
        return 2;

    int x = 8, y = 70, dx = 2, night = 0;
    while (arc1_running()) {
        arc1_input_poll();
        uint32_t held = arc1_input_held(0);
        if (arc1_input_pressed(0) & ARC1_BTN_A) night = !night;
        if ((held & ARC1_BTN_UP) && y > 0) y -= 2;
        if ((held & ARC1_BTN_DOWN) && y < ARC1_SCREEN_H - 16 - ARC1_ASSET_SHIP_H) y += 2;

        x += dx;
        if (x <= 0 || x >= ARC1_SCREEN_W - ARC1_ASSET_SHIP_W) dx = -dx;

        if (arc1_frame_begin(0) != ARC1_OK) return 3;
        draw_sky(night, arc1_frame_index());
        arc1_sprite_draw(ship, x, y);
        arc1_frame_end();
    }
    return 0;
}
